22	    password: string,
23	    fullName: string
24	  ) => Promise<{ error: AuthError | null }>;
25	  signInWithGoogle: () => Promise<{ error: AuthError | null }>;
26	  signOut: () => Promise<void>;
27	  refreshProfile: () => Promise<void>;
28	}
29	
30	// ── Context ───────────────────────────────────────────────────
31	
32	const AuthContext = createContext<AuthContextValue | null>(null);
33	
34	// ── Provider ──────────────────────────────────────────────────
35	
36	export function AuthProvider({ children }: { children: ReactNode }) {
37	  const [user, setUser] = useState<User | null>(null);
38	  const [profile, setProfile] = useState<UserProfile | null>(null);
39	  const [loading, setLoading] = useState(true);
40	
41	  const fetchProfile = useCallback(async (userId: string) => {
42	    const { data, error } = await supabase
43	      .from("profiles")
44	      .select(
45	        "id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, created_at, billing_cycle_end"
46	      )
47	      .eq("id", userId)
48	      .single();
49	
50	    if (error) {
51	      console.error("Failed to fetch profile:", error.message);
52	      setProfile(null);
53	      return;
54	    }
55	
56	    setProfile(data as UserProfile);
57	  }, []);
58	
59	  const refreshProfile = useCallback(async () => {
60	    if (!user) return;
61	    await fetchProfile(user.id);
62	  }, [user, fetchProfile]);
63	
64	  useEffect(() => {
65	    // Resolve initial session without waiting for the listener
66	    supabase.auth.getSession().then(({ data: { session } }) => {
67	      setUser(session?.user ?? null);
68	      if (session?.user) {
69	        fetchProfile(session.user.id).finally(() => setLoading(false));
70	      } else {
71	        setLoading(false);
72	      }
73	    });
74	
75	    const {
76	      data: { subscription },
77	    } = supabase.auth.onAuthStateChange((_event, session) => {
78	      setUser(session?.user ?? null);
79	      if (session?.user) {
80	        fetchProfile(session.user.id);
81	      } else {
82	        setProfile(null);
83	      }
84	    });
85	
86	    return () => subscription.unsubscribe();
87	  }, [fetchProfile]);
88	
89	  // ── Auth actions ─────────────────────────────────────────────
90	
91	  const signIn = async (email: string, password: string) => {
92	    const { error } = await supabase.auth.signInWithPassword({ email, password });
93	    return { error };
94	  };
95	
96	  const signUp = async (email: string, password: string, fullName: string) => {
97	    const { error } = await supabase.auth.signUp({
98	      email,
99	      password,
100	      options: {
101	        data: { full_name: fullName },
102	        emailRedirectTo: `${window.location.origin}/auth/callback`,
103	      },
104	    });
105	    return { error };
106	  };
107	
108	  const signInWithGoogle = async () => {
109	    const { error } = await supabase.auth.signInWithOAuth({
110	      provider: "google",
111	      options: {
112	        redirectTo: `${window.location.origin}/auth/callback`,
113	      },
114	    });
115	    return { error };
116	  };
117	
118	  const signOut = async () => {
119	    await supabase.auth.signOut();
120	    setUser(null);
121	    setProfile(null);
122	  };
123	
124	  return (
125	    <AuthContext.Provider
126	      value={{
127	        user,
128	        profile,
129	        loading,
130	        signIn,
131	        signUp,
132	        signInWithGoogle,
133	        signOut,
134	        refreshProfile,
135	      }}
136	    >
137	      {children}
138	    </AuthContext.Provider>
139	  );
140	}
141	
142	// ── Hook ──────────────────────────────────────────────────────
143	
144	export function useAuth(): AuthContextValue {
145	  const ctx = useContext(AuthContext);
146	  if (!ctx) {
147	    throw new Error("useAuth must be used inside <AuthProvider>");
148	  }
149	  return ctx;
150	}
