import { loadStripe } from "@stripe/stripe-js";

const stripePromise = loadStripe(
  import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY || ""
);

export default stripePromise;

import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { PlanType } from "@/types";

// ── useCheckout ──────────────────────────────────────────────────
// Initiates a Stripe Checkout session for the given plan + billing cycle.
// On success, redirects the browser to Stripe-hosted checkout.

export function useCheckout() {
  return useMutation({
    mutationFn: async ({
      plan,
      billingCycle,
    }: {
      plan: Exclude<PlanType, "free">;
      billingCycle: "monthly" | "annual";
    }) => {
      const { data, error } = await supabase.functions.invoke(
        "stripe-checkout",
        {
          body: { plan, billing_cycle: billingCycle },
        }
      );

      if (error) {
        throw new Error(
          error.message || "Failed to start checkout. Please try again."
        );
      }

      if (!data?.url) {
        throw new Error("No checkout URL returned from server.");
      }

      return data.url as string;
    },
    onSuccess: (url) => {
      window.location.href = url;
    },
    onError: (error: unknown) => {
      const message =
        error instanceof Error ? error.message : "Checkout failed.";
      toast.error(message);
    },
  });
}

// ── useCustomerPortal ────────────────────────────────────────────
// Opens the Stripe Customer Portal so users can manage their subscription,
// payment method, and invoices.

export function useCustomerPortal() {
  return useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.functions.invoke("stripe-portal");

      if (error) {
        throw new Error(
          error.message || "Failed to open billing portal. Please try again."
        );
      }

      if (!data?.url) {
        throw new Error("No portal URL returned from server.");
      }

      return data.url as string;
    },
    onSuccess: (url) => {
      window.location.href = url;
    },
    onError: (error: unknown) => {
      const message =
        error instanceof Error ? error.message : "Failed to open portal.";
      toast.error(message);
    },
  });
}

// ── useUsage ─────────────────────────────────────────────────────
// Returns current scan usage derived from the authenticated user's profile.
// No network call — reads from AuthContext which is kept fresh.

export function useUsage() {
  const { profile } = useAuth();

  if (!profile) {
    return {
      scansUsed: 0,
      scanLimit: 0,
      usagePercent: 0,
      plan: "free" as PlanType,
      billingCycleEnd: null as string | null,
    };
  }

  const usagePercent =
    profile.scan_limit > 0
      ? Math.min((profile.scans_used / profile.scan_limit) * 100, 100)
      : 0;

  return {
    scansUsed: profile.scans_used,
    scanLimit: profile.scan_limit,
    usagePercent,
    plan: profile.plan,
    billingCycleEnd: profile.billing_cycle_end ?? null,
  };
}

/**
 * stripe-checkout — Edge Function
 *
 * Creates a Stripe Checkout Session for plan upgrades.
 *
 * Expected request body:
 *   { plan: 'pro' | 'agency'; billing_cycle: 'monthly' | 'annual' }
 *
 * Returns:
 *   { url: string } — Stripe-hosted checkout page URL
 *
 * Required env vars:
 *   STRIPE_SECRET_KEY
 *   STRIPE_PRICE_PRO_MONTHLY
 *   STRIPE_PRICE_PRO_ANNUAL
 *   STRIPE_PRICE_AGENCY_MONTHLY
 *   STRIPE_PRICE_AGENCY_ANNUAL
 *   SITE_URL  (for success/cancel redirect URLs)
 *   SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import Stripe from "https://esm.sh/stripe@14?target=deno";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

// Price ID lookup table — driven by env vars to avoid hardcoding
function getPriceId(plan: string, billingCycle: string): string | null {
  const map: Record<string, string> = {
    "pro:monthly": Deno.env.get("STRIPE_PRICE_PRO_MONTHLY") ?? "",
    "pro:annual": Deno.env.get("STRIPE_PRICE_PRO_ANNUAL") ?? "",
    "agency:monthly": Deno.env.get("STRIPE_PRICE_AGENCY_MONTHLY") ?? "",
    "agency:annual": Deno.env.get("STRIPE_PRICE_AGENCY_ANNUAL") ?? "",
  };
  return map[`${plan}:${billingCycle}`] || null;
}

serve(async (req: Request) => {
  // Handle CORS preflight
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    // ── 1. Auth — verify the JWT and extract user ──────────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: "Missing Authorization header" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Use anon client with user's JWT to resolve identity
    const supabaseUser = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
      { global: { headers: { Authorization: authHeader } } }
    );

    const {
      data: { user },
      error: userError,
    } = await supabaseUser.auth.getUser();

    if (userError || !user) {
      return new Response(
        JSON.stringify({ error: "Unauthorized" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 2. Parse + validate body ───────────────────────────────────
    let body: { plan?: string; billing_cycle?: string };
    try {
      body = await req.json();
    } catch {
      return new Response(
        JSON.stringify({ error: "Invalid JSON body" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const { plan, billing_cycle } = body;

    if (!plan || !["pro", "agency"].includes(plan)) {
      return new Response(
        JSON.stringify({ error: "Invalid plan. Must be 'pro' or 'agency'." }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    if (!billing_cycle || !["monthly", "annual"].includes(billing_cycle)) {
      return new Response(
        JSON.stringify({ error: "Invalid billing_cycle. Must be 'monthly' or 'annual'." }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const priceId = getPriceId(plan, billing_cycle);
    if (!priceId) {
      console.error(`Missing price ID for ${plan}:${billing_cycle}`);
      return new Response(
        JSON.stringify({ error: "Pricing configuration error. Contact support." }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 3. Get user's profile — check for existing Stripe customer ──
    // Use service role key for full DB access
    const supabaseAdmin = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
    );

    const { data: profile, error: profileError } = await supabaseAdmin
      .from("profiles")
      .select("id, email, full_name, stripe_customer_id")
      .eq("id", user.id)
      .single();

    if (profileError || !profile) {
      console.error("Profile fetch error:", profileError);
      return new Response(
        JSON.stringify({ error: "User profile not found." }),
        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 4. Stripe — find or create customer ───────────────────────
    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") ?? "", {
      apiVersion: "2024-06-20",
      httpClient: Stripe.createFetchHttpClient(),
    });

    let stripeCustomerId: string = profile.stripe_customer_id ?? "";

    if (!stripeCustomerId) {
      const customer = await stripe.customers.create({
        email: profile.email ?? user.email,
        name: profile.full_name ?? undefined,
        metadata: { supabase_user_id: user.id },
      });
      stripeCustomerId = customer.id;

      // Persist the new customer ID immediately
      const { error: updateError } = await supabaseAdmin
        .from("profiles")
        .update({ stripe_customer_id: stripeCustomerId })
        .eq("id", user.id);

      if (updateError) {
        // Non-fatal — checkout can proceed, customer ID will be captured from webhook
        console.error("Failed to persist stripe_customer_id:", updateError);
      }
    }

    // ── 5. Create Checkout Session ─────────────────────────────────
    const origin = Deno.env.get("SITE_URL") ?? "http://localhost:5173";

    const session = await stripe.checkout.sessions.create({
      customer: stripeCustomerId,
      mode: "subscription",
      line_items: [{ price: priceId, quantity: 1 }],
      success_url: `${origin}/dashboard?checkout=success`,
      cancel_url: `${origin}/pricing?checkout=cancelled`,
      allow_promotion_codes: true,
      subscription_data: {
        metadata: {
          user_id: user.id,
          plan,
        },
      },
      metadata: {
        user_id: user.id,
        plan,
      },
    });

    return new Response(
      JSON.stringify({ url: session.url }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Internal server error";
    console.error("stripe-checkout error:", error);
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

/**
 * stripe-portal — Edge Function
 *
 * Creates a Stripe Billing Portal session so users can manage their
 * subscription, payment method, and download invoices.
 *
 * Returns:
 *   { url: string } — Stripe-hosted portal URL
 *
 * Required env vars:
 *   STRIPE_SECRET_KEY
 *   SITE_URL               (for return_url redirect)
 *   SUPABASE_URL
 *   SUPABASE_ANON_KEY
 *   SUPABASE_SERVICE_ROLE_KEY
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import Stripe from "https://esm.sh/stripe@14?target=deno";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    // ── 1. Auth ────────────────────────────────────────────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: "Missing Authorization header" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const supabaseUser = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
      { global: { headers: { Authorization: authHeader } } }
    );

    const {
      data: { user },
      error: userError,
    } = await supabaseUser.auth.getUser();

    if (userError || !user) {
      return new Response(
        JSON.stringify({ error: "Unauthorized" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 2. Get profile and stripe_customer_id ──────────────────────
    const supabaseAdmin = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
    );

    const { data: profile, error: profileError } = await supabaseAdmin
      .from("profiles")
      .select("stripe_customer_id")
      .eq("id", user.id)
      .single();

    if (profileError || !profile?.stripe_customer_id) {
      return new Response(
        JSON.stringify({
          error: "No active subscription found. Please upgrade to a paid plan first.",
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 3. Create Billing Portal session ──────────────────────────
    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") ?? "", {
      apiVersion: "2024-06-20",
      httpClient: Stripe.createFetchHttpClient(),
    });

    const origin = Deno.env.get("SITE_URL") ?? "http://localhost:5173";

    const portalSession = await stripe.billingPortal.sessions.create({
      customer: profile.stripe_customer_id,
      return_url: `${origin}/settings?tab=billing`,
    });

    return new Response(
      JSON.stringify({ url: portalSession.url }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Internal server error";
    console.error("stripe-portal error:", error);
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

/**
 * stripe-webhook — Edge Function
 *
 * Handles incoming Stripe webhook events and keeps the profiles table
 * in sync with subscription state.
 *
 * Handled events:
 *   checkout.session.completed     → activate plan, set scan_limit, billing_cycle_end
 *   customer.subscription.updated  → sync plan changes (upgrade / downgrade)
 *   customer.subscription.deleted  → downgrade to free, clear billing data
 *   invoice.payment_failed         → log failure for observability
 *
 * Required env vars:
 *   STRIPE_SECRET_KEY
 *   STRIPE_WEBHOOK_SECRET          (from Stripe dashboard → webhook endpoint)
 *   SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY
 *
 * Security: Stripe-Signature header is verified before any processing.
 * No auth cookie / JWT required — Stripe calls this endpoint directly.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import Stripe from "https://esm.sh/stripe@14?target=deno";

// ── Plan config ───────────────────────────────────────────────────

type PlanType = "free" | "pro" | "agency";

const PLAN_LIMITS: Record<PlanType, number> = {
  free: 3,
  pro: 50,
  agency: 500,
};

// Derive plan from Stripe price IDs at runtime
function getPlanFromPriceId(priceId: string): PlanType {
  const proMonthly = Deno.env.get("STRIPE_PRICE_PRO_MONTHLY");
  const proAnnual = Deno.env.get("STRIPE_PRICE_PRO_ANNUAL");
  const agencyMonthly = Deno.env.get("STRIPE_PRICE_AGENCY_MONTHLY");
  const agencyAnnual = Deno.env.get("STRIPE_PRICE_AGENCY_ANNUAL");

  if (priceId === proMonthly || priceId === proAnnual) return "pro";
  if (priceId === agencyMonthly || priceId === agencyAnnual) return "agency";

  // Unknown price ID — default safe
  console.warn(`Unknown price ID: ${priceId}. Defaulting to 'pro'.`);
  return "pro";
}

// ── Serve ─────────────────────────────────────────────────────────

serve(async (req: Request) => {
  // Webhook endpoint does NOT handle CORS OPTIONS — Stripe never sends preflight.
  // Only POST requests arrive here.

  const signature = req.headers.get("stripe-signature");
  if (!signature) {
    return new Response(
      JSON.stringify({ error: "Missing Stripe-Signature header" }),
      { status: 400, headers: { "Content-Type": "application/json" } }
    );
  }

  const webhookSecret = Deno.env.get("STRIPE_WEBHOOK_SECRET");
  if (!webhookSecret) {
    console.error("STRIPE_WEBHOOK_SECRET env var not set");
    return new Response(
      JSON.stringify({ error: "Webhook secret not configured" }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }

  const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") ?? "", {
    apiVersion: "2024-06-20",
    httpClient: Stripe.createFetchHttpClient(),
  });

  // ── Verify signature ─────────────────────────────────────────────
  const body = await req.text();
  let event: Stripe.Event;

  try {
    event = await stripe.webhooks.constructEventAsync(body, signature, webhookSecret);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Invalid signature";
    console.error("Webhook signature verification failed:", message);
    return new Response(
      JSON.stringify({ error: `Webhook verification failed: ${message}` }),
      { status: 400, headers: { "Content-Type": "application/json" } }
    );
  }

  // ── Admin Supabase client (bypasses RLS) ─────────────────────────
  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  // ── Event routing ─────────────────────────────────────────────────
  try {
    switch (event.type) {
      // ── checkout.session.completed ───────────────────────────────
      case "checkout.session.completed": {
        const session = event.data.object as Stripe.Checkout.Session;
        const userId = session.metadata?.user_id;
        const plan = (session.metadata?.plan ?? "pro") as PlanType;

        if (!userId) {
          console.error("checkout.session.completed: missing user_id in metadata");
          break;
        }

        // Fetch the created subscription to get billing period end
        let billingCycleEnd: string | null = null;
        if (session.subscription) {
          const subscription = await stripe.subscriptions.retrieve(
            session.subscription as string
          );
          billingCycleEnd = new Date(
            subscription.current_period_end * 1000
          ).toISOString();
        }

        const { error } = await supabase
          .from("profiles")
          .update({
            plan,
            scan_limit: PLAN_LIMITS[plan] ?? PLAN_LIMITS.pro,
            stripe_subscription_id: session.subscription ?? null,
            billing_cycle_end: billingCycleEnd,
            updated_at: new Date().toISOString(),
          })
          .eq("id", userId);

        if (error) {
          console.error("checkout.session.completed profile update error:", error);
        } else {
          console.log(`Activated ${plan} plan for user ${userId}`);
        }
        break;
      }

      // ── customer.subscription.updated ────────────────────────────
      case "customer.subscription.updated": {
        const subscription = event.data.object as Stripe.Subscription;

        // Find user by stripe_customer_id
        const { data: profile, error: profileError } = await supabase
          .from("profiles")
          .select("id, plan")
          .eq("stripe_customer_id", subscription.customer as string)
          .single();

        if (profileError || !profile) {
          console.error(
            "customer.subscription.updated: profile not found for customer",
            subscription.customer
          );
          break;
        }

        // Derive new plan from the subscription's first price item
        const priceId = subscription.items.data[0]?.price?.id;
        const newPlan: PlanType = priceId
          ? getPlanFromPriceId(priceId)
          : profile.plan;

        const billingCycleEnd = new Date(
          subscription.current_period_end * 1000
        ).toISOString();

        // Map subscription status to plan — cancelled/past_due → keep current until period end
        const isActive =
          subscription.status === "active" ||
          subscription.status === "trialing";

        const { error } = await supabase
          .from("profiles")
          .update({
            plan: isActive ? newPlan : profile.plan,
            scan_limit: isActive
              ? PLAN_LIMITS[newPlan] ?? PLAN_LIMITS.pro
              : PLAN_LIMITS[profile.plan as PlanType] ?? PLAN_LIMITS.free,
            stripe_subscription_id: subscription.id,
            billing_cycle_end: billingCycleEnd,
            updated_at: new Date().toISOString(),
          })
          .eq("id", profile.id);

        if (error) {
          console.error("customer.subscription.updated profile update error:", error);
        } else {
          console.log(
            `Updated subscription for user ${profile.id}: ${profile.plan} → ${newPlan} (status: ${subscription.status})`
          );
        }
        break;
      }

      // ── customer.subscription.deleted ────────────────────────────
      case "customer.subscription.deleted": {
        const subscription = event.data.object as Stripe.Subscription;

        const { data: profile, error: profileError } = await supabase
          .from("profiles")
          .select("id")
          .eq("stripe_customer_id", subscription.customer as string)
          .single();

        if (profileError || !profile) {
          console.error(
            "customer.subscription.deleted: profile not found for customer",
            subscription.customer
          );
          break;
        }

        const { error } = await supabase
          .from("profiles")
          .update({
            plan: "free",
            scan_limit: PLAN_LIMITS.free,
            stripe_subscription_id: null,
            billing_cycle_end: null,
            updated_at: new Date().toISOString(),
          })
          .eq("id", profile.id);

        if (error) {
          console.error("customer.subscription.deleted profile update error:", error);
        } else {
          console.log(`Downgraded user ${profile.id} to free plan (subscription deleted)`);
        }
        break;
      }

      // ── invoice.payment_failed ────────────────────────────────────
      case "invoice.payment_failed": {
        const invoice = event.data.object as Stripe.Invoice;
        console.log(
          `Payment failed for customer ${invoice.customer} — invoice ${invoice.id} — amount ${invoice.amount_due} ${invoice.currency}`
        );
        // Future: trigger a dunning email via send-email function
        break;
      }

      default:
        // Unhandled event type — acknowledge receipt to avoid retries
        console.log(`Unhandled webhook event type: ${event.type}`);
    }

    return new Response(
      JSON.stringify({ received: true }),
      { status: 200, headers: { "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Handler error";
    console.error(`Error handling ${event.type}:`, error);
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }
});

import { useState } from "react";
