const COMPARISON_ROWS = [
  { feature: "Page scans per month", free: "3", pro: "50", agency: "500" },
  { feature: "CRO pillars analyzed", free: "7", pro: "7", agency: "7" },
  { feature: "Suggestions per scan", free: "Top 3 only", pro: "All", agency: "All" },
  { feature: "AI copy rewrites", free: false, pro: true, agency: true },
  { feature: "PDF report export", free: false, pro: true, agency: true },
  { feature: "Monthly score monitoring", free: false, pro: true, agency: true },
  { feature: "Industry benchmark comparison", free: false, pro: true, agency: true },
